import math

def lr_lambda(step, T_warmup, T_total, eta_peak, eta_final=0.0):
    if step < T_warmup:
        # Linear warmup
        return eta_peak * step / T_warmup
    # Cosine decay
    progress = (step - T_warmup) / (T_total - T_warmup)
    return eta_final + 0.5 * (eta_peak - eta_final) * (1 + math.cos(math.pi * progress))
